results.script:
(
{BillableCTC} <= 1000000
? (
    MarkUp = Math.min({BillableCTC} * 0.0833, 300000),
    ExecutedServiceTerms = MarkUp == 300000 ? "8.33% (Capped at 300000)" : "8.33%"
  )

: ({BillableCTC} >= 1000001 && {BillableCTC} <= 3000000)

? (
    MarkUp = Math.min({BillableCTC} * 0.10, 300000),
    ExecutedServiceTerms = MarkUp == 300000 ? "10% (Capped at 300000)" : "10%"
  )

: (
    MarkUp = Math.min({BillableCTC} * 0.125, 300000),
    ExecutedServiceTerms = MarkUp == 300000 ? "12.5% (Capped at 300000)" : "12.5%"
  )
);

ReplacementPeriod = 60;
